"use client";

import * as React from "react"

import {
  ArrowLeftIcon,
  ArrowRightIcon,
  ClipboardListIcon,
  Columns2Icon,
  EditIcon,
  FolderIcon,
  GitBranchIcon,
  GridIcon,
  HelpCircleIcon,
  HistoryIcon,
  HomeIcon,
  InboxIcon,
  MoonIcon,
  PanelRightIcon,
  PlusIcon,
  SettingsIcon,
  SidebarIcon,
  TerminalSquareIcon,
} from "@/components/icons"
import { cn } from "@/lib/utils"
import { CommandPalette, type CommandPaletteItem } from "@/registry/base-nova/blocks/command-palette/command-palette"
import { BottomSheet, BottomSheetContent, BottomSheetTitle } from "@/registry/base-nova/ui/bottom-sheet"
import { Button } from "@/registry/base-nova/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/registry/base-nova/ui/dialog"
import { Drawer, DrawerContent, DrawerTitle } from "@/registry/base-nova/ui/drawer"
import { FileDiff } from "@/registry/base-nova/ui/file-diff"
import { IconRail, IconRailAvatar, IconRailGroup, IconRailItem, IconRailSpacer } from "@/registry/base-nova/ui/icon-rail"
import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
  type ResizablePanelGroupHandle,
} from "@/registry/base-nova/ui/resizable"
import { TabStrip, TabStripItem } from "@/registry/base-nova/ui/tab-strip"
import { useThemeToggle } from "@/registry/base-nova/ui/theme-toggle"
import { Tooltip, TooltipContent, TooltipKbd, TooltipProvider, TooltipTrigger } from "@/registry/base-nova/ui/tooltip"

import { AcpClient, useAcpClient, type EditedFileState } from "./acp/client"
import { DEMO_CWD, DEMO_STATUS, DEMO_TERMINAL } from "./acp/demo-data"
import { createMockTransport } from "./acp/mock-agent"
import { createWebSocketTransport } from "./acp/transport"
import { DEMO_AGENT, loadAgents, loadBridge, saveAgents, saveBridge, type AgentConfig, type BridgeConfig } from "./parts/agents"
import { ChatPane } from "./parts/chat-pane"
import { Dock, type DockTab } from "./parts/dock"
import { ProviderIcon } from "./parts/provider-icon"
import { SettingsDialog } from "./parts/settings-dialog"
import { ThreadsSidebar, type ThreadSummary } from "./parts/threads-sidebar"

const DEMO_TABS = ["sess_scrollbar", "sess_hide_empty", "sess_split_close", "sess_fix_drag"]

/** Below `md` the workspace switches to its phone layout. */
const MOBILE_QUERY = "(max-width: 767.98px)"

function useIsMobile() {
  return React.useSyncExternalStore(
    (onChange) => {
      const mq = window.matchMedia(MOBILE_QUERY)
      mq.addEventListener("change", onChange)
      return () => mq.removeEventListener("change", onChange)
    },
    () => window.matchMedia(MOBILE_QUERY).matches,
    () => false
  )
}

function ToolbarButton({
  label,
  shortcut,
  onClick,
  pressed,
  size = "icon-sm",
  children,
}: {
  label: string
  shortcut?: string
  onClick?: () => void
  pressed?: boolean
  size?: "icon-sm" | "icon"
  children: React.ReactNode
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button variant="ghost" size={size} aria-label={label} aria-pressed={pressed} onClick={onClick} className={cn("text-muted-foreground", pressed && "text-foreground")}>
            {children}
          </Button>
        }
      />
      <TooltipContent side="bottom">
        {label}
        {shortcut && <TooltipKbd>{shortcut}</TooltipKbd>}
      </TooltipContent>
    </Tooltip>
  )
}

/**
 * Multi-provider coding-agent workspace, wired to the Agent Client Protocol:
 * an icon rail, a threads sidebar, tabs of open threads, one or two chat
 * panes and a dock with terminal, explorer and browser. Below `md` it becomes
 * a phone layout: a header with the tabs, the rail and threads in a drawer,
 * the dock in a bottom sheet and one full-width chat (no split).
 * Starts on the offline demo agent; Settings → Agents connects real ACP
 * agents through server/acp-bridge.mjs.
 */
export function AgentWorkspace() {
  const client = React.useMemo(() => new AcpClient(), [])
  const state = useAcpClient(client)
  const { toggle: toggleTheme } = useThemeToggle()

  const [agents, setAgents] = React.useState<AgentConfig[]>([DEMO_AGENT])
  const [bridge, setBridge] = React.useState<BridgeConfig>({ url: "ws://127.0.0.1:8787", token: "" })
  const [agentId, setAgentId] = React.useState("demo")
  const [settingsOpen, setSettingsOpen] = React.useState(false)
  const [paletteOpen, setPaletteOpen] = React.useState(false)

  const [tabs, setTabs] = React.useState<string[]>([])
  const [left, setLeft] = React.useState<string | null>(null)
  const [right, setRight] = React.useState<string | null>(null)
  const [focus, setFocus] = React.useState<"left" | "right">("left")
  const history = React.useRef<{ stack: string[]; index: number }>({ stack: [], index: -1 })
  const [autofixDismissed, setAutofixDismissed] = React.useState<Record<string, boolean>>({})
  const [review, setReview] = React.useState<EditedFileState[] | null>(null)

  const [sidebarOpen, setSidebarOpen] = React.useState(true)
  const [dockOpen, setDockOpen] = React.useState(true)
  const [dockTab, setDockTab] = React.useState<DockTab>("terminal")
  const [dockTabs, setDockTabs] = React.useState<DockTab[]>(["terminal", "explorer", "browser"])
  const [explorerPath, setExplorerPath] = React.useState<string | null>(null)
  const outer = React.useRef<ResizablePanelGroupHandle>(null)
  const inner = React.useRef<ResizablePanelGroupHandle>(null)

  const mobile = useIsMobile()
  const [navOpen, setNavOpen] = React.useState(false)
  const [dockSheetOpen, setDockSheetOpen] = React.useState(false)

  const active = focus === "right" && right && !mobile ? right : left
  const agent = agents.find((a) => a.id === agentId) ?? DEMO_AGENT

  /* ------------------------------ threads ------------------------------- */

  const threads = React.useMemo<ThreadSummary[]>(() => {
    const listed = state.sessionList.map((info) => {
      const meta = (info._meta ?? {}) as Partial<ThreadSummary>
      const s = state.sessions[info.sessionId]
      return {
        sessionId: info.sessionId,
        title: s?.title ?? info.title ?? "Thread",
        provider: meta.provider,
        repo: meta.repo,
        pr: meta.pr,
        branch: meta.branch,
        group: meta.group ?? "Recent",
        running: s?.status === "working",
      }
    })
    const local = Object.values(state.sessions)
      .filter((s) => !state.sessionList.some((i) => i.sessionId === s.id))
      .map((s) => ({
        sessionId: s.id,
        title: s.title,
        provider: agent.provider,
        repo: s.cwd.split("/").filter(Boolean).pop(),
        group: "Recent",
        running: s.status === "working",
      }))
    return [...local.reverse(), ...listed]
  }, [state.sessionList, state.sessions, agent.provider])

  const threadOf = (id: string | null) => threads.find((t) => t.sessionId === id)

  const ensureLoaded = React.useCallback(
    (id: string) => {
      if (client.getState().sessions[id]) return
      const info = client.getState().sessionList.find((i) => i.sessionId === id)
      if (info) void client.loadSession(id, info.cwd, info.title ?? undefined).catch(() => undefined)
    },
    [client]
  )

  const show = React.useCallback(
    (id: string, pane: "left" | "right" = focus, record = true) => {
      ensureLoaded(id)
      setTabs((t) => (t.includes(id) ? t : [...t, id]))
      if (pane === "right" && right) setRight(id)
      else setLeft(id)
      if (record) {
        const h = history.current
        h.stack = [...h.stack.slice(0, h.index + 1), id]
        h.index = h.stack.length - 1
      }
    },
    [ensureLoaded, focus, right]
  )

  const go = (d: -1 | 1) => {
    const h = history.current
    const next = h.index + d
    if (next < 0 || next >= h.stack.length) return
    h.index = next
    show(h.stack[next], focus, false)
  }

  const closeTab = (id: string) => {
    const i = tabs.indexOf(id)
    const rest = tabs.filter((t) => t !== id)
    setTabs(rest)
    if (right === id) {
      setRight(null)
      setFocus("left")
    }
    if (left === id) setLeft(rest[Math.min(i, rest.length - 1)] ?? null)
  }

  const newThread = React.useCallback(async () => {
    if (client.getState().connection !== "ready") return
    const cwd = client.getState().workspaceRoot ?? DEMO_CWD
    const id = await client.newSession(cwd)
    show(id)
  }, [client, show])

  const fork = async (text: string) => {
    const id = await client.newSession(client.getState().workspaceRoot ?? DEMO_CWD)
    show(id)
    if (text) void client.prompt(id, `Continue from this answer:\n\n${text.slice(0, 600)}`)
  }

  const toggleSplit = () => {
    if (mobile) return
    if (right) {
      setRight(null)
      setFocus("left")
      return
    }
    const other = tabs.find((t) => t !== left)
    if (other) {
      ensureLoaded(other)
      setRight(other)
      setFocus("right")
    }
  }

  /* ----------------------------- connection ----------------------------- */

  const connect = React.useCallback(
    async (target: AgentConfig, bridgeConfig: BridgeConfig) => {
      setAgentId(target.id)
      setTabs([])
      setLeft(null)
      setRight(null)
      history.current = { stack: [], index: -1 }
      if (target.builtin) {
        await client.connect(createMockTransport(), { clientCapabilities: { fs: { readTextFile: false, writeTextFile: false }, terminal: false } })
        await client.refreshFiles()
        client.setTerminal("user-1", DEMO_TERMINAL)
        await client.listSessions(DEMO_CWD)
        setTabs(DEMO_TABS)
        DEMO_TABS.forEach((id) => client.getState().sessions[id] || void client.loadSession(id, DEMO_CWD).catch(() => undefined))
        setLeft("sess_fix_drag")
        history.current = { stack: ["sess_fix_drag"], index: 0 }
        return
      }
      const url = `${bridgeConfig.url.replace(/\/$/, "")}/?token=${encodeURIComponent(bridgeConfig.token)}`
      try {
        const transport = await createWebSocketTransport(url)
        await client.connect(transport, {
          beforeInitialize: (c) => c.request("_bridge/spawn", { command: target.command, args: target.args, env: target.env }),
        })
        const files = await client.refreshFiles().catch(() => [])
        void files
        client.setTerminal("user-1", "", "Terminal")
        const root = client.getState().workspaceRoot ?? "/"
        await client.listSessions(root).catch(() => [])
        const id = await client.newSession(root)
        setTabs([id])
        setLeft(id)
      } catch (err) {
        // The client already records the error on its state; keep the settings open so it shows.
        setSettingsOpen(true)
        void err
      }
    },
    [client]
  )

  // Restore saved agents and bridge address, then start on the demo agent.
  React.useEffect(() => {
    setAgents(loadAgents())
    setBridge(loadBridge())
    void connect(DEMO_AGENT, loadBridge())
    return () => client.disconnect()
  }, [client, connect])

  // Tablets (md to lg): open with the dock collapsed so the chat keeps its 360px minimum.
  React.useEffect(() => {
    if (!mobile && window.matchMedia("(max-width: 1023.98px)").matches) inner.current?.collapse("dock")
  }, [mobile])

  /* ----------------------------- shortcuts ------------------------------ */

  const toggleSidebar = () => (mobile ? setNavOpen((o) => !o) : outer.current?.toggle("threads"))
  const toggleDock = () => (mobile ? setDockSheetOpen((o) => !o) : inner.current?.toggle("dock"))

  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (!(e.metaKey || e.ctrlKey) || e.altKey) return
      const k = e.key.toLowerCase()
      if (k === "b") toggleSidebar()
      else if (k === "j") toggleDock()
      else if (k === "n") void newThread()
      else if (k === "\\") toggleSplit()
      else if (k === ",") setSettingsOpen(true)
      else if (/^[1-9]$/.test(k) && tabs[Number(k) - 1]) show(tabs[Number(k) - 1])
      else return
      e.preventDefault()
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  })

  const paletteItems: CommandPaletteItem[] = [
    { id: "new", label: "New thread", group: "Threads", shortcut: ["⌘", "N"], icon: EditIcon, onSelect: () => void newThread() },
    ...(mobile ? [] : [{ id: "split", label: right ? "Close split view" : "Split chats side by side", group: "View", shortcut: ["⌘", "\\"], icon: Columns2Icon, onSelect: toggleSplit }]),
    { id: "sidebar", label: "Toggle threads sidebar", group: "View", shortcut: ["⌘", "B"], icon: SidebarIcon, onSelect: toggleSidebar },
    { id: "dock", label: "Toggle terminal panel", group: "View", shortcut: ["⌘", "J"], icon: TerminalSquareIcon, onSelect: toggleDock },
    { id: "theme", label: "Toggle dark mode", group: "View", icon: MoonIcon, onSelect: toggleTheme },
    { id: "agents", label: "Manage agents…", group: "Settings", shortcut: ["⌘", ","], icon: SettingsIcon, onSelect: () => setSettingsOpen(true) },
    ...threads.map((t) => ({ id: `t-${t.sessionId}`, label: t.title, group: "Open thread", description: t.branch, icon: HistoryIcon, onSelect: () => show(t.sessionId) })),
  ]

  /* ------------------------------- render ------------------------------- */

  const statusLine = agent.builtin
    ? DEMO_STATUS
    : `\u001b[34m${state.agentInfo?.title ?? state.agentInfo?.name ?? agent.name}\u001b[0m  \u001b[2m${state.workspaceRoot ?? ""}\u001b[0m  ${state.connection === "ready" ? "\u001b[32m● connected\u001b[0m" : `\u001b[31m● ${state.connection}\u001b[0m`}`

  const pane = (id: string | null, side: "left" | "right") => (
    <ChatPane
      client={client}
      state={state}
      session={id ? state.sessions[id] : undefined}
      thread={threadOf(id)}
      focused={focus === side}
      onFocus={() => setFocus(side)}
      showAutofix={!!id && !autofixDismissed[id]}
      onDismissAutofix={() => id && setAutofixDismissed((d) => ({ ...d, [id]: true }))}
      onReview={setReview}
      onFork={(text) => void fork(text)}
      onReveal={(path) => {
        setExplorerPath(path)
        setDockTabs((t) => (t.includes("explorer") ? t : [...t, "explorer"]))
        setDockTab("explorer")
        if (mobile) setDockSheetOpen(true)
        else inner.current?.expand("dock")
      }}
    />
  )

  const closeNav = () => setNavOpen(false)

  const rail = (orientation: "vertical" | "horizontal") => {
    const horizontal = orientation === "horizontal"
    // In the phone drawer, items that open something else close the drawer first.
    const then = (fn: () => void) => () => {
      if (horizontal) closeNav()
      fn()
    }
    return (
      <IconRail aria-label="App" orientation={orientation}>
        <IconRailGroup>
          <IconRailItem label="Home" icon={<HomeIcon />} onClick={then(() => left && show(left))} />
          <IconRailItem label="Inbox" icon={<InboxIcon />} />
          <IconRailItem label="Tasks" icon={<ClipboardListIcon />} />
          <IconRailItem
            label="Branches"
            icon={<GitBranchIcon />}
            onClick={then(() => {
              setDockTab("explorer")
              if (horizontal) setDockSheetOpen(true)
            })}
          />
          <IconRailItem label="History" shortcut="⌘K" icon={<HistoryIcon />} onClick={then(() => setPaletteOpen(true))} />
          <IconRailItem label="Agents" icon={<GridIcon />} onClick={then(() => setSettingsOpen(true))} />
          {!horizontal && <IconRailItem label="Threads" shortcut="⌘B" icon={<FolderIcon />} active={sidebarOpen} onClick={toggleSidebar} />}
        </IconRailGroup>
        <IconRailSpacer />
        <IconRailGroup>
          {/* The phone row has room for the connected agent only; the rest are in the threads header menu. */}
          {(horizontal ? agents.filter((a) => a.id === agentId) : agents.slice(0, 3)).map((a) => (
            <IconRailAvatar
              key={a.id}
              label={a.name}
              hint={a.id === agentId ? state.connection : "not connected"}
              status={a.id !== agentId ? "offline" : state.connection === "ready" ? "online" : state.connection === "connecting" ? "busy" : "error"}
              onClick={then(() => (a.builtin ? void connect(a, bridge) : setSettingsOpen(true)))}
            >
              <ProviderIcon provider={a.provider} />
            </IconRailAvatar>
          ))}
          <IconRailItem label="Command palette" shortcut="⌘K" icon={<HelpCircleIcon />} onClick={then(() => setPaletteOpen(true))} />
          <IconRailItem label="Settings" shortcut="⌘," icon={<SettingsIcon />} onClick={then(() => setSettingsOpen(true))} />
        </IconRailGroup>
      </IconRail>
    )
  }

  const sidebar = (
    <ThreadsSidebar
      threads={threads}
      activeId={active}
      onSelect={(id) => {
        show(id)
        closeNav()
      }}
      onNewThread={() => {
        closeNav()
        void newThread()
      }}
      agents={agents}
      agentId={agentId}
      onSelectAgent={(id) => {
        const a = agents.find((x) => x.id === id)
        if (a?.builtin) void connect(a, bridge)
        else setSettingsOpen(true)
      }}
      onOpenSettings={() => {
        closeNav()
        setSettingsOpen(true)
      }}
    />
  )

  const tabStrip = (
    <TabStrip
      value={active}
      onValueChange={(id) => show(id)}
      order={tabs}
      onReorder={setTabs}
      onClose={closeTab}
      aria-label="Open threads"
      className="min-w-0 flex-1"
    >
      {tabs.map((id) => {
        const t = threadOf(id)
        return (
          <TabStripItem key={id} value={id} icon={<ProviderIcon provider={t?.provider} />} indicator={t?.running} className={mobile ? "w-32" : "w-36"}>
            {t?.title ?? state.sessions[id]?.title ?? "Thread"}
          </TabStripItem>
        )
      })}
    </TabStrip>
  )

  const errorBanner =
    state.connection === "error" ? (
      <div role="alert" className="flex items-center gap-2 border-b border-destructive-border bg-destructive-subtle px-4 py-2 text-ui text-destructive">
        <span className="min-w-0 flex-1 truncate">{state.error ?? "Disconnected"}</span>
        <Button variant="outline" size="xs" onClick={() => setSettingsOpen(true)}>
          Agent settings
        </Button>
      </div>
    ) : null

  const emptyState = (
    <div className="flex h-full flex-col items-center justify-center gap-3 p-6 text-center">
      <p className="text-ui text-muted-foreground">{state.connection === "connecting" ? "Connecting…" : "No thread open."}</p>
      <Button variant="secondary" onClick={() => void newThread()} disabled={state.connection !== "ready"}>
        <EditIcon data-icon="inline-start" />
        New thread
      </Button>
    </div>
  )

  const dock = (onCollapse: () => void, compact = false) => (
    <Dock
      client={client}
      state={state}
      tab={dockTab}
      onTabChange={setDockTab}
      tabs={dockTabs}
      onTabsChange={setDockTabs}
      onCollapse={onCollapse}
      explorerPath={explorerPath}
      onExplorerPath={setExplorerPath}
      status={statusLine}
      compact={compact}
    />
  )

  return (
    <TooltipProvider>
      {mobile ? (
        /* Phone layout: header (threads, tabs, new, panel), one full-width chat. */
        <div className="flex h-dvh w-full flex-col overflow-hidden bg-shell text-foreground">
          <header className="flex h-12 shrink-0 items-center gap-1 px-1.5">
            <ToolbarButton label="Threads and navigation" shortcut="⌘B" size="icon" pressed={navOpen} onClick={() => setNavOpen(true)}>
              <SidebarIcon />
            </ToolbarButton>
            {tabStrip}
            <ToolbarButton label="New thread" shortcut="⌘N" size="icon" onClick={() => void newThread()}>
              <PlusIcon />
            </ToolbarButton>
            <ToolbarButton label="Terminal, files and browser" shortcut="⌘J" size="icon" pressed={dockSheetOpen} onClick={() => setDockSheetOpen(true)}>
              <TerminalSquareIcon />
            </ToolbarButton>
          </header>
          <main className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-t-shell border-t border-shell-border bg-background">
            {errorBanner}
            <div className="min-h-0 flex-1">{left ? pane(left, "left") : emptyState}</div>
          </main>
        </div>
      ) : (
        <div className="flex h-dvh w-full overflow-hidden bg-shell text-foreground">
          {rail("vertical")}

          <ResizablePanelGroup direction="horizontal" autoSaveId="agent-workspace-shell" handleRef={outer} className="min-w-0 flex-1">
            <ResizablePanel id="threads" defaultSize="248px" minSize="220px" maxSize="420px" collapsible onCollapsedChange={(c) => setSidebarOpen(!c)}>
              <div className="flex h-full flex-col">
                <div className="mt-[3.5px] flex h-10 shrink-0 items-center gap-1 px-2">
                  <ToolbarButton label="Hide sidebar" shortcut="⌘B" onClick={toggleSidebar}>
                    <SidebarIcon />
                  </ToolbarButton>
                  <ToolbarButton label="Back" onClick={() => go(-1)}>
                    <ArrowLeftIcon className="rtl:-scale-x-100" />
                  </ToolbarButton>
                  <ToolbarButton label="Forward" onClick={() => go(1)}>
                    <ArrowRightIcon className="rtl:-scale-x-100" />
                  </ToolbarButton>
                </div>
                <div className="min-h-0 flex-1">{sidebar}</div>
              </div>
            </ResizablePanel>
            <ResizableHandle variant="hidden" />
            <ResizablePanel id="main" minSize={40}>
              <div className="shell-inset mt-0.75 flex h-full min-h-0 flex-col overflow-hidden">
                <ResizablePanelGroup direction="horizontal" autoSaveId="agent-workspace-content" handleRef={inner}>
                  <ResizablePanel id="chat" minSize="360px">
                    <div className="flex h-full min-w-0 flex-col">
                      <div className="flex h-10 shrink-0 items-center gap-1 border-b border-border px-2">
                        {!sidebarOpen && (
                          <ToolbarButton label="Show sidebar" shortcut="⌘B" onClick={toggleSidebar}>
                            <SidebarIcon />
                          </ToolbarButton>
                        )}
                        {tabStrip}
                        <ToolbarButton label={right ? "Close split" : "Split chats"} shortcut="⌘\" pressed={!!right} onClick={toggleSplit}>
                          <Columns2Icon />
                        </ToolbarButton>
                        <ToolbarButton label="New thread" shortcut="⌘N" onClick={() => void newThread()}>
                          <PlusIcon />
                        </ToolbarButton>
                        <ToolbarButton label={dockOpen ? "Hide panel" : "Show panel"} shortcut="⌘J" pressed={dockOpen} onClick={toggleDock}>
                          <PanelRightIcon />
                        </ToolbarButton>
                      </div>
                      <div className="min-h-0 flex-1">
                        {errorBanner}
                        {right ? (
                          <ResizablePanelGroup direction="horizontal" autoSaveId="agent-workspace-split">
                            <ResizablePanel id="left" minSize="320px">
                              {pane(left, "left")}
                            </ResizablePanel>
                            <ResizableHandle />
                            <ResizablePanel id="right" minSize="320px">
                              {pane(right, "right")}
                            </ResizablePanel>
                          </ResizablePanelGroup>
                        ) : left ? (
                          pane(left, "left")
                        ) : (
                          emptyState
                        )}
                      </div>
                    </div>
                  </ResizablePanel>
                  <ResizableHandle />
                  <ResizablePanel id="dock" defaultSize={44} minSize="300px" collapsible onCollapsedChange={(c) => setDockOpen(!c)}>
                    {dock(() => inner.current?.collapse("dock"))}
                  </ResizablePanel>
                </ResizablePanelGroup>
              </div>
            </ResizablePanel>
          </ResizablePanelGroup>
        </div>
      )}

      {mobile && (
        <>
          <Drawer side="left" open={navOpen} onOpenChange={setNavOpen}>
            <DrawerContent showClose={false} className="p-0">
              <DrawerTitle className="sr-only">Threads</DrawerTitle>
              <div className="min-h-0 flex-1 pt-2">{sidebar}</div>
              <div className="shrink-0 border-t border-border">{rail("horizontal")}</div>
            </DrawerContent>
          </Drawer>
          <BottomSheet open={dockSheetOpen} onOpenChange={setDockSheetOpen} snapPoints={[0.6, 0.92]}>
            <BottomSheetContent className="max-w-none">
              <BottomSheetTitle className="sr-only">Terminal, files and browser</BottomSheetTitle>
              <div className="min-h-0 flex-1">{dock(() => setDockSheetOpen(false), true)}</div>
            </BottomSheetContent>
          </BottomSheet>
        </>
      )}

      <CommandPalette items={paletteItems} open={paletteOpen} onOpenChange={setPaletteOpen} placeholder="Search threads and commands…" />

      <SettingsDialog
        open={settingsOpen}
        onOpenChange={setSettingsOpen}
        agents={agents}
        onAgentsChange={(next) => {
          setAgents(next)
          saveAgents(next)
        }}
        bridge={bridge}
        onBridgeChange={(next) => {
          setBridge(next)
          saveBridge(next)
        }}
        activeAgentId={agentId}
        connection={state.connection}
        error={state.error}
        onConnect={(id) => {
          const target = agents.find((a) => a.id === id)
          if (target) void connect(target, bridge)
        }}
      />

      <Dialog open={review !== null} onOpenChange={(o) => !o && setReview(null)}>
        <DialogContent className="max-w-4xl">
          <DialogHeader>
            <DialogTitle>Review changes</DialogTitle>
            <DialogDescription>
              {review?.length ?? 0} {review?.length === 1 ? "file" : "files"} changed in this turn.
            </DialogDescription>
          </DialogHeader>
          <div className="flex flex-col gap-3">
            {review?.map((f) => (
              <FileDiff
                key={f.path}
                filename={f.path.replace(`${state.sessions[active ?? ""]?.cwd ?? ""}/`, "")}
                oldFile={f.oldText}
                newFile={f.newText}
                diffStyleToggle
                defaultOpen={review.length < 4}
                maxHeight={420}
              />
            ))}
          </div>
        </DialogContent>
      </Dialog>
    </TooltipProvider>
  )
}

"use client";

import * as React from "react"
import type * as acp from "@agentclientprotocol/sdk"

import type { AcpTransport, JsonRpcId, JsonRpcMessage } from "./transport"

/**
 * A typed Agent Client Protocol (ACP) client for the browser.
 *
 * It speaks JSON-RPC 2.0 over any `AcpTransport`, keeps one store per session
 * (streamed `session/update` notifications folded into a chat timeline, tool
 * calls, plan, modes, config options, slash commands) and exposes it to React
 * through `useAcpClient`. Wire types come from the official
 * `@agentclientprotocol/sdk` package (type-only, so nothing ships to the
 * browser); the runtime is a few hundred lines so the template stays light.
 *
 * Methods: initialize, session/new, session/load, session/list,
 * session/prompt, session/cancel, session/set_mode, session/set_config_option,
 * session/set_model (unstable, used by claude-code-acp). Agent → client:
 * session/update, session/request_permission. fs/* and terminal/* are served
 * by the bridge (server/acp-bridge.mjs) next to the agent, which also sends
 * `_bridge/*` extension notifications (terminal output, file writes).
 */

export const PROTOCOL_VERSION = 1

/* -------------------------------------------------------------------------- */
/*  State model                                                               */
/* -------------------------------------------------------------------------- */

export type ToolCallState = acp.ToolCall & { startedAt: number; endedAt?: number }

export type EditedFileState = { path: string; oldText: string | null; newText: string | null }

export type PermissionItem = {
  kind: "permission"
  id: string
  at: number
  requestId: JsonRpcId
  toolCall: acp.ToolCallUpdate
  options: acp.PermissionOption[]
  /** Chosen option id, `"cancelled"`, or undefined while pending. */
  outcome?: string
}

export type TimelineItem =
  | { kind: "user"; id: string; at: number; text: string; steering?: boolean }
  | { kind: "assistant"; id: string; at: number; text: string; streaming: boolean; messageId?: string | null }
  | { kind: "work"; id: string; startedAt: number; endedAt?: number; toolCallIds: string[]; thoughts: string }
  | { kind: "edits"; id: string; at: number; files: EditedFileState[]; undone?: boolean }
  | { kind: "notice"; id: string; at: number; text: string; tone: "info" | "error" }
  | PermissionItem

/** Unstable `models` block some agents (claude-code-acp) return from session/new. */
export type AgentModelState = {
  currentModelId: string
  availableModels: { modelId: string; name: string; description?: string | null }[]
}

export type SessionState = {
  id: string
  cwd: string
  title: string
  status: "idle" | "working" | "loading"
  timeline: TimelineItem[]
  toolCalls: Record<string, ToolCallState>
  plan: acp.PlanEntry[]
  modes: acp.SessionModeState | null
  configOptions: acp.SessionConfigOption[]
  models: AgentModelState | null
  commands: acp.AvailableCommand[]
  usage: { used: number; size: number } | null
  turnStartedAt?: number
  lastStopReason?: acp.StopReason
  /** Extension data an agent attached to the session (`_meta`), e.g. repo / branch / PR for the sidebar. */
  meta?: Record<string, unknown>
}

export type TerminalState = {
  id: string
  title: string
  output: string
  exitStatus?: acp.TerminalExitStatus | null
  sessionId?: string
}

export type ClientState = {
  connection: "disconnected" | "connecting" | "ready" | "error"
  transportLabel: string
  error?: string
  agentInfo?: acp.Implementation | null
  agentCapabilities?: acp.AgentCapabilities
  authMethods: acp.AuthMethod[]
  /** Sessions the agent reported through session/list (not loaded yet). */
  sessionList: (acp.SessionInfo & { _meta?: Record<string, unknown> | null })[]
  sessions: Record<string, SessionState>
  terminals: Record<string, TerminalState>
  /** Workspace files, for @mentions and the explorer (from the bridge or the demo agent). */
  files: string[]
  workspaceRoot?: string
  /** Agent stderr and bridge messages. */
  log: string[]
}

const INITIAL: ClientState = {
  connection: "disconnected",
  transportLabel: "",
  authMethods: [],
  sessionList: [],
  sessions: {},
  terminals: {},
  files: [],
  log: [],
}

class RpcError extends Error {
  code: number
  data?: unknown
  constructor(code: number, message: string, data?: unknown) {
    super(message)
    this.code = code
    this.data = data
  }
}

let uid = 0
const nextId = (p: string) => `${p}-${Date.now().toString(36)}-${(uid++).toString(36)}`

function textOf(block: acp.ContentBlock): string {
  switch (block.type) {
    case "text":
      return block.text
    case "resource_link":
      return `[${block.name}](${block.uri})`
    case "resource":
      return "text" in block.resource ? block.resource.text : ""
    case "image":
      return "[image]"
    case "audio":
      return "[audio]"
    default:
      return ""
  }
}

/** Timestamp an agent attached to an update (`_meta.timestamp`, epoch ms or ISO), else now. */
function stampOf(update: { _meta?: { [key: string]: unknown } | null }) {
  const t = update._meta?.timestamp
  if (typeof t === "number") return t
  if (typeof t === "string") {
    const n = Date.parse(t)
    if (!Number.isNaN(n)) return n
  }
  return Date.now()
}

function emptySession(id: string, cwd: string, title = "New thread"): SessionState {
  return {
    id,
    cwd,
    title,
    status: "idle",
    timeline: [],
    toolCalls: {},
    plan: [],
    modes: null,
    configOptions: [],
    models: null,
    commands: [],
    usage: null,
  }
}

/* -------------------------------------------------------------------------- */
/*  Client                                                                    */
/* -------------------------------------------------------------------------- */

type Pending = { resolve: (v: unknown) => void; reject: (e: unknown) => void }

export type ConnectOptions = {
  clientInfo?: acp.Implementation
  clientCapabilities?: acp.ClientCapabilities
  /** Runs after the transport is attached and before `initialize` (the bridge's `_bridge/spawn`). */
  beforeInitialize?: (client: AcpClient) => Promise<unknown>
}

export class AcpClient {
  private state: ClientState = INITIAL
  private listeners = new Set<() => void>()
  private transport: AcpTransport | null = null
  private unsubs: (() => void)[] = []
  private pending = new Map<JsonRpcId, Pending>()
  private permissionWaiters = new Map<string, (r: acp.RequestPermissionResponse) => void>()
  private promptRuns = new Map<string, Promise<acp.PromptResponse | null>>()
  /** Files written through fs/write_text_file during the current turn, per session. */
  private turnWrites = new Map<string, Map<string, EditedFileState>>()
  private rid = 1
  private frame: number | null = null

  /* ---------------------------- store plumbing ---------------------------- */

  getState = () => this.state

  subscribe = (listener: () => void) => {
    this.listeners.add(listener)
    return () => {
      this.listeners.delete(listener)
    }
  }

  private set(fn: (s: ClientState) => ClientState) {
    this.state = fn(this.state)
    // Coalesce bursts of streamed chunks into one render per frame.
    if (this.frame !== null) return
    const flush = () => {
      this.frame = null
      for (const l of [...this.listeners]) l()
    }
    this.frame = typeof requestAnimationFrame === "function" ? requestAnimationFrame(flush) : (setTimeout(flush, 16) as unknown as number)
  }

  private patchSession(id: string, fn: (s: SessionState) => SessionState) {
    this.set((st) => {
      const cur = st.sessions[id]
      if (!cur) return st
      return { ...st, sessions: { ...st.sessions, [id]: fn(cur) } }
    })
  }

  private log(line: string) {
    this.set((s) => ({ ...s, log: [...s.log.slice(-199), line] }))
  }

  /* ------------------------------ JSON-RPC -------------------------------- */

  private send(message: Omit<JsonRpcMessage, "jsonrpc">) {
    this.transport?.send({ jsonrpc: "2.0", ...message })
  }

  /** Send a request and await its result. */
  request<T = unknown>(method: string, params?: unknown): Promise<T> {
    if (!this.transport) return Promise.reject(new Error("Not connected"))
    const id = this.rid++
    return new Promise<T>((resolve, reject) => {
      this.pending.set(id, { resolve: resolve as (v: unknown) => void, reject })
      this.send({ id, method, params })
    })
  }

  notify(method: string, params?: unknown) {
    this.send({ method, params })
  }

  private onMessage = (msg: JsonRpcMessage) => {
    if (msg.method && msg.id !== undefined && msg.id !== null) {
      void this.handleRequest(msg.id, msg.method, msg.params)
    } else if (msg.method) {
      this.handleNotification(msg.method, msg.params)
    } else if (msg.id !== undefined && msg.id !== null) {
      const p = this.pending.get(msg.id)
      if (!p) return
      this.pending.delete(msg.id)
      if (msg.error) p.reject(new RpcError(msg.error.code, msg.error.message, msg.error.data))
      else p.resolve(msg.result)
    }
  }

  private async handleRequest(id: JsonRpcId, method: string, params: unknown) {
    try {
      let result: unknown
      if (method === "session/request_permission") result = await this.onPermission(id, params as acp.RequestPermissionRequest)
      else throw new RpcError(-32601, `Method not found: ${method} (the browser client serves fs and terminal through the bridge)`)
      this.send({ id, result })
    } catch (err) {
      const e = err instanceof RpcError ? err : new RpcError(-32603, err instanceof Error ? err.message : String(err))
      this.send({ id, error: { code: e.code, message: e.message, data: e.data } })
    }
  }

  private handleNotification(method: string, params: unknown) {
    switch (method) {
      case "session/update": {
        const { sessionId, update } = params as acp.SessionNotification
        this.applyUpdate(sessionId, update)
        return
      }
      case "_bridge/terminal_output": {
        const p = params as { terminalId: string; data: string; title?: string; sessionId?: string }
        this.set((s) => {
          const t = s.terminals[p.terminalId] ?? { id: p.terminalId, title: p.title ?? "Terminal", output: "", sessionId: p.sessionId }
          return { ...s, terminals: { ...s.terminals, [p.terminalId]: { ...t, output: t.output + p.data } } }
        })
        return
      }
      case "_bridge/terminal_exit": {
        const p = params as { terminalId: string; exitStatus: acp.TerminalExitStatus }
        this.set((s) => {
          const t = s.terminals[p.terminalId]
          return t ? { ...s, terminals: { ...s.terminals, [p.terminalId]: { ...t, exitStatus: p.exitStatus } } } : s
        })
        return
      }
      case "_bridge/fs_write": {
        const p = params as { sessionId: string; path: string; oldText: string | null; newText: string }
        const writes = this.turnWrites.get(p.sessionId) ?? new Map<string, EditedFileState>()
        const prev = writes.get(p.path)
        writes.set(p.path, { path: p.path, oldText: prev ? prev.oldText : p.oldText, newText: p.newText })
        this.turnWrites.set(p.sessionId, writes)
        return
      }
      case "_bridge/files": {
        const p = params as { files: string[]; root?: string }
        this.set((s) => ({ ...s, files: p.files, workspaceRoot: p.root ?? s.workspaceRoot }))
        return
      }
      case "_bridge/agent_stderr":
        this.log(String((params as { data: string }).data).trimEnd())
        return
      case "_bridge/agent_exit": {
        const p = params as { code: number | null; signal: string | null }
        this.set((s) => ({ ...s, connection: "error", error: `Agent exited (${p.signal ?? `code ${p.code}`})` }))
        return
      }
      default:
        // Unknown extension notifications are ignored, as ACP asks.
        return
    }
  }

  /* ----------------------------- connection ------------------------------- */

  async connect(transport: AcpTransport, options: ConnectOptions = {}) {
    this.disconnect()
    this.transport = transport
    this.set((s) => ({ ...INITIAL, connection: "connecting", transportLabel: transport.label, files: s.files }))
    this.unsubs.push(transport.onMessage(this.onMessage))
    this.unsubs.push(
      transport.onClose((reason) => {
        this.failPending(new Error(reason))
        this.set((s) => ({ ...s, connection: "error", error: reason }))
      })
    )
    try {
      await options.beforeInitialize?.(this)
      const res = await this.request<acp.InitializeResponse>("initialize", {
        protocolVersion: PROTOCOL_VERSION,
        clientCapabilities: options.clientCapabilities ?? { fs: { readTextFile: true, writeTextFile: true }, terminal: true },
        clientInfo: options.clientInfo ?? { name: "qinyang-agent-workspace", title: "Agent Workspace", version: "1.0.0" },
      } satisfies acp.InitializeRequest)
      this.set((s) => ({
        ...s,
        connection: "ready",
        agentInfo: res.agentInfo,
        agentCapabilities: res.agentCapabilities,
        authMethods: res.authMethods ?? [],
      }))
      return res
    } catch (err) {
      this.set((s) => ({ ...s, connection: "error", error: err instanceof Error ? err.message : String(err) }))
      throw err
    }
  }

  disconnect() {
    for (const u of this.unsubs) u()
    this.unsubs = []
    this.failPending(new Error("Disconnected"))
    for (const resolve of this.permissionWaiters.values()) resolve({ outcome: { outcome: "cancelled" } })
    this.permissionWaiters.clear()
    this.transport?.close()
    this.transport = null
  }

  private failPending(err: Error) {
    for (const p of this.pending.values()) p.reject(err)
    this.pending.clear()
  }

  /** Run an `authenticate` method the agent advertised. */
  authenticate(methodId: string) {
    return this.request<acp.AuthenticateResponse>("authenticate", { methodId } satisfies acp.AuthenticateRequest)
  }

  /* ------------------------------- sessions ------------------------------- */

  async newSession(cwd: string, mcpServers: acp.McpServer[] = []) {
    const res = await this.request<acp.NewSessionResponse & { models?: AgentModelState | null }>("session/new", {
      cwd,
      mcpServers,
    } satisfies acp.NewSessionRequest)
    this.set((s) => ({
      ...s,
      sessions: {
        ...s.sessions,
        [res.sessionId]: {
          ...emptySession(res.sessionId, cwd),
          modes: res.modes ?? null,
          configOptions: res.configOptions ?? [],
          models: res.models ?? null,
        },
      },
    }))
    return res.sessionId
  }

  /** List the agent's past sessions (when it supports `session/list`). */
  async listSessions(cwd?: string) {
    if (!this.state.agentCapabilities?.sessionCapabilities?.list) return []
    const res = await this.request<acp.ListSessionsResponse>("session/list", cwd ? { cwd } : {})
    this.set((s) => ({ ...s, sessionList: res.sessions }))
    return res.sessions
  }

  /** Re-open a past session; the agent replays it as session/update notifications. */
  async loadSession(sessionId: string, cwd: string, title?: string) {
    if (this.state.sessions[sessionId]) return sessionId
    const info = this.state.sessionList.find((x) => x.sessionId === sessionId)
    this.set((s) => ({
      ...s,
      sessions: {
        ...s.sessions,
        [sessionId]: { ...emptySession(sessionId, cwd, title ?? info?.title ?? "Thread"), status: "loading", meta: info?._meta ?? undefined },
      },
    }))
    const res = await this.request<acp.LoadSessionResponse & { models?: AgentModelState | null }>("session/load", {
      sessionId,
      cwd,
      mcpServers: [],
    } satisfies acp.LoadSessionRequest)
    this.finishTurn(sessionId)
    this.patchSession(sessionId, (s) => ({
      ...s,
      status: "idle",
      modes: res?.modes ?? s.modes,
      configOptions: res?.configOptions ?? s.configOptions,
      models: res?.models ?? s.models,
    }))
    return sessionId
  }

  /** Forget a session locally (closing its tab keeps it in the list; this removes it). */
  dropSession(sessionId: string) {
    this.set((s) => {
      const sessions = { ...s.sessions }
      delete sessions[sessionId]
      return { ...s, sessions }
    })
  }

  /**
   * Send a prompt. `@path` mentions become `resource_link` blocks. If the
   * agent is still working the current turn is cancelled first and the
   * message is marked as steering the conversation.
   */
  async prompt(sessionId: string, text: string) {
    const session = this.state.sessions[sessionId]
    if (!session) throw new Error(`Unknown session ${sessionId}`)
    const steering = session.status === "working"
    if (steering) {
      await this.cancel(sessionId)
      await this.promptRuns.get(sessionId)?.catch(() => null)
    }
    const now = Date.now()
    this.patchSession(sessionId, (s) => ({
      ...s,
      status: "working",
      turnStartedAt: now,
      title: s.timeline.some((i) => i.kind === "user") || s.title !== "New thread" ? s.title : text.slice(0, 60),
      timeline: [...s.timeline, { kind: "user", id: nextId("u"), at: now, text, steering }],
    }))
    const blocks: acp.ContentBlock[] = [{ type: "text", text }]
    const root = session.cwd.replace(/\/$/, "")
    for (const m of text.matchAll(/(?:^|\s)@([^\s]+)/g)) {
      const path = m[1]
      blocks.push({ type: "resource_link", name: path, uri: `file://${path.startsWith("/") ? path : `${root}/${path}`}` })
    }
    const run = this.request<acp.PromptResponse>("session/prompt", { sessionId, prompt: blocks } satisfies acp.PromptRequest)
      .then((res) => {
        this.finishTurn(sessionId, res.stopReason)
        return res
      })
      .catch((err: unknown) => {
        this.finishTurn(sessionId)
        let text = err instanceof Error ? err.message : String(err)
        // Point at the agent's own sign-in route when it asks for authentication.
        const auth = this.state.authMethods[0]
        if (/auth/i.test(text) && auth) text += `. ${auth.description ?? auth.name}`
        this.patchSession(sessionId, (s) => ({
          ...s,
          timeline: [...s.timeline, { kind: "notice", id: nextId("n"), at: Date.now(), tone: "error", text }],
        }))
        return null
      })
    this.promptRuns.set(sessionId, run)
    return run
  }

  /** `session/cancel`; pending permission requests resolve as cancelled, as the spec requires. */
  async cancel(sessionId: string) {
    this.notify("session/cancel", { sessionId } satisfies acp.CancelNotification)
    for (const item of this.state.sessions[sessionId]?.timeline ?? []) {
      if (item.kind === "permission" && item.outcome === undefined) this.resolvePermission(sessionId, item.id, null)
    }
  }

  async setMode(sessionId: string, modeId: string) {
    const prev = this.state.sessions[sessionId]?.modes?.currentModeId
    this.patchSession(sessionId, (s) => (s.modes ? { ...s, modes: { ...s.modes, currentModeId: modeId } } : s))
    try {
      await this.request<acp.SetSessionModeResponse>("session/set_mode", { sessionId, modeId } satisfies acp.SetSessionModeRequest)
    } catch (err) {
      if (prev) this.patchSession(sessionId, (s) => (s.modes ? { ...s, modes: { ...s.modes, currentModeId: prev } } : s))
      throw err
    }
  }

  async setConfigOption(sessionId: string, configId: string, value: string) {
    this.patchSession(sessionId, (s) => ({
      ...s,
      configOptions: s.configOptions.map((o) => (o.id === configId && o.type === "select" ? { ...o, currentValue: value } : o)),
    }))
    const res = await this.request<acp.SetSessionConfigOptionResponse>("session/set_config_option", {
      sessionId,
      configId,
      value,
    } satisfies acp.SetSessionConfigOptionRequest)
    if (res?.configOptions) this.patchSession(sessionId, (s) => ({ ...s, configOptions: res.configOptions }))
  }

  /** Unstable `session/set_model` (agents that return `models` instead of a model config option). */
  async setModel(sessionId: string, modelId: string) {
    this.patchSession(sessionId, (s) => (s.models ? { ...s, models: { ...s.models, currentModelId: modelId } } : s))
    await this.request("session/set_model", { sessionId, modelId })
  }

  /* ----------------------------- permissions ------------------------------ */

  private onPermission(requestId: JsonRpcId, params: acp.RequestPermissionRequest) {
    const id = nextId("perm")
    this.patchSession(params.sessionId, (s) => ({
      ...s,
      timeline: [...s.timeline, { kind: "permission", id, at: Date.now(), requestId, toolCall: params.toolCall, options: params.options }],
    }))
    return new Promise<acp.RequestPermissionResponse>((resolve) => {
      this.permissionWaiters.set(id, resolve)
    })
  }

  /** Answer a permission request with one of its option ids, or `null` to cancel. */
  resolvePermission(sessionId: string, itemId: string, optionId: string | null) {
    const resolve = this.permissionWaiters.get(itemId)
    this.permissionWaiters.delete(itemId)
    this.patchSession(sessionId, (s) => ({
      ...s,
      timeline: s.timeline.map((i) => (i.id === itemId && i.kind === "permission" ? { ...i, outcome: optionId ?? "cancelled" } : i)),
    }))
    resolve?.(optionId ? { outcome: { outcome: "selected", optionId } } : { outcome: { outcome: "cancelled" } })
  }

  /* ------------------------------- bridge --------------------------------- */

  /** Run a shell command in the workspace through the bridge; output streams into `terminals[terminalId]`. */
  async runShell(command: string, terminalId: string) {
    this.set((s) => {
      const t = s.terminals[terminalId] ?? { id: terminalId, title: "Terminal", output: "" }
      return { ...s, terminals: { ...s.terminals, [terminalId]: { ...t, output: `${t.output}\u001b[2m❯\u001b[22m ${command}\n`, exitStatus: undefined } } }
    })
    return this.request<{ exitCode: number | null }>("_bridge/exec", { command, terminalId })
  }

  /** Seed or clear a terminal locally (demo content, the clear button). */
  setTerminal(terminalId: string, output: string, title = "Terminal") {
    this.set((s) => ({ ...s, terminals: { ...s.terminals, [terminalId]: { id: terminalId, title, output } } }))
  }

  async refreshFiles() {
    const res = await this.request<{ files: string[]; root: string }>("_bridge/list_files", {})
    this.set((s) => ({ ...s, files: res.files, workspaceRoot: res.root }))
    return res.files
  }

  readFile(path: string) {
    return this.request<{ content: string }>("_bridge/read_file", { path })
  }

  /** Revert an "Edited files" card: restore every file's old text (delete files the turn created). */
  async undoEdits(sessionId: string, itemId: string) {
    const item = this.state.sessions[sessionId]?.timeline.find((i) => i.id === itemId)
    if (!item || item.kind !== "edits") return
    for (const f of item.files) {
      await this.request("_bridge/write_file", { path: f.path, content: f.oldText }).catch((err: unknown) =>
        this.log(`Undo failed for ${f.path}: ${err instanceof Error ? err.message : String(err)}`)
      )
    }
    this.patchSession(sessionId, (s) => ({
      ...s,
      timeline: s.timeline.map((i) => (i.id === itemId && i.kind === "edits" ? { ...i, undone: true } : i)),
    }))
  }

  /* ------------------------------- updates -------------------------------- */

  private applyUpdate(sessionId: string, update: acp.SessionUpdate) {
    if (!this.state.sessions[sessionId]) {
      // An agent may stream into a session before session/new resolves.
      this.set((s) => ({ ...s, sessions: { ...s.sessions, [sessionId]: emptySession(sessionId, s.workspaceRoot ?? "") } }))
    }
    const at = stampOf(update)
    this.patchSession(sessionId, (s) => reduceUpdate(s, update, at, () => this.finishTurnState(s, sessionId)))
  }

  /** Close a turn: settle open work groups and summarise the files it changed. */
  private finishTurn(sessionId: string, stopReason?: acp.StopReason) {
    this.patchSession(sessionId, (s) => ({ ...this.finishTurnState(s, sessionId), status: "idle", lastStopReason: stopReason }))
  }

  private finishTurnState(s: SessionState, sessionId: string): SessionState {
    const now = Date.now()
    // Turn boundary: the last user message.
    let start = s.timeline.length
    for (let i = s.timeline.length - 1; i >= 0; i--) {
      if (s.timeline[i].kind === "user") break
      start = i
    }
    const turn = s.timeline.slice(start)
    if (turn.some((i) => i.kind === "edits")) return { ...s, timeline: s.timeline.map((i) => settle(i, now)) }
    const files = new Map<string, EditedFileState>()
    for (const item of turn) {
      if (item.kind !== "work") continue
      for (const id of item.toolCallIds) {
        for (const c of s.toolCalls[id]?.content ?? []) {
          if (c.type !== "diff") continue
          const prev = files.get(c.path)
          files.set(c.path, { path: c.path, oldText: prev ? prev.oldText : (c.oldText ?? null), newText: c.newText })
        }
      }
    }
    for (const w of this.turnWrites.get(sessionId)?.values() ?? []) {
      const prev = files.get(w.path)
      files.set(w.path, { path: w.path, oldText: prev ? prev.oldText : w.oldText, newText: w.newText })
    }
    this.turnWrites.delete(sessionId)
    const lastAt = turn.reduce((t, i) => Math.max(t, "at" in i ? i.at : (i.endedAt ?? i.startedAt)), 0)
    const timeline = s.timeline.map((i) => settle(i, lastAt || now))
    if (files.size) timeline.push({ kind: "edits", id: nextId("e"), at: lastAt || now, files: [...files.values()] })
    return { ...s, timeline }
  }
}

function settle(item: TimelineItem, at: number): TimelineItem {
  if (item.kind === "work" && item.endedAt === undefined) return { ...item, endedAt: at }
  if (item.kind === "assistant" && item.streaming) return { ...item, streaming: false }
  return item
}

/** Fold one `session/update` into a session (pure, apart from the turn-close callback). */
function reduceUpdate(s: SessionState, update: acp.SessionUpdate, at: number, closeTurn: () => SessionState): SessionState {
  const timeline = s.timeline
  const last = timeline[timeline.length - 1]

  /** The open work group at the end of the timeline, or a new one. */
  const withWork = (fn: (w: Extract<TimelineItem, { kind: "work" }>) => Extract<TimelineItem, { kind: "work" }>) => {
    if (last?.kind === "work" && last.endedAt === undefined) return [...timeline.slice(0, -1), fn(last)]
    return [...timeline.map((i) => settle(i, at)), fn({ kind: "work", id: nextId("w"), startedAt: at, toolCallIds: [], thoughts: "" })]
  }

  switch (update.sessionUpdate) {
    case "user_message_chunk": {
      // Replayed history (session/load): a user message closes the previous turn.
      const text = textOf(update.content)
      if (last?.kind === "user" && (update.messageId == null || last.id === update.messageId)) {
        return { ...s, timeline: [...timeline.slice(0, -1), { ...last, text: last.text + text }] }
      }
      const closed = closeTurn()
      const steering = update._meta?.steering === true
      return {
        ...closed,
        title: closed.title === "Thread" || closed.title === "New thread" ? text.slice(0, 60) : closed.title,
        timeline: [...closed.timeline, { kind: "user", id: update.messageId ?? nextId("u"), at, text, steering }],
      }
    }
    case "agent_message_chunk": {
      const text = textOf(update.content)
      if (last?.kind === "assistant" && last.streaming && (update.messageId == null || last.messageId == null || last.messageId === update.messageId)) {
        return { ...s, timeline: [...timeline.slice(0, -1), { ...last, text: last.text + text }] }
      }
      return {
        ...s,
        timeline: [
          ...timeline.map((i) => settle(i, at)),
          { kind: "assistant", id: nextId("a"), at, text, streaming: true, messageId: update.messageId },
        ],
      }
    }
    case "agent_thought_chunk": {
      const text = textOf(update.content)
      return { ...s, timeline: withWork((w) => ({ ...w, thoughts: w.thoughts + text })) }
    }
    case "tool_call": {
      const { sessionUpdate, ...call } = update
      void sessionUpdate
      const known = s.toolCalls[call.toolCallId]
      const tc: ToolCallState = {
        ...known,
        ...call,
        startedAt: known?.startedAt ?? at,
        endedAt: call.status === "completed" || call.status === "failed" ? at : undefined,
      }
      const inTimeline = timeline.some((i) => i.kind === "work" && i.toolCallIds.includes(call.toolCallId))
      return {
        ...s,
        toolCalls: { ...s.toolCalls, [call.toolCallId]: tc },
        timeline: inTimeline ? timeline : withWork((w) => ({ ...w, toolCallIds: [...w.toolCallIds, call.toolCallId] })),
      }
    }
    case "tool_call_update": {
      const { sessionUpdate, ...patch } = update
      void sessionUpdate
      const prev = s.toolCalls[patch.toolCallId] ?? { toolCallId: patch.toolCallId, title: patch.title ?? "Tool call", startedAt: at }
      const next: ToolCallState = { ...prev }
      if (patch.title != null) next.title = patch.title
      if (patch.kind != null) next.kind = patch.kind
      if (patch.status != null) next.status = patch.status
      if (patch.content != null) next.content = patch.content
      if (patch.locations != null) next.locations = patch.locations
      if (patch.rawInput !== undefined) next.rawInput = patch.rawInput
      if (patch.rawOutput !== undefined) next.rawOutput = patch.rawOutput
      if (patch.status === "completed" || patch.status === "failed") next.endedAt = at
      const inTimeline = timeline.some((i) => i.kind === "work" && i.toolCallIds.includes(patch.toolCallId))
      return {
        ...s,
        toolCalls: { ...s.toolCalls, [patch.toolCallId]: next },
        timeline: inTimeline ? timeline : withWork((w) => ({ ...w, toolCallIds: [...w.toolCallIds, patch.toolCallId] })),
      }
    }
    case "plan":
      return { ...s, plan: update.entries }
    case "available_commands_update":
      return { ...s, commands: update.availableCommands }
    case "current_mode_update":
      return s.modes ? { ...s, modes: { ...s.modes, currentModeId: update.currentModeId } } : s
    case "config_option_update":
      return { ...s, configOptions: update.configOptions }
    case "session_info_update":
      return update.title ? { ...s, title: update.title } : s
    case "usage_update":
      return { ...s, usage: { used: update.used, size: update.size } }
    default:
      return s
  }
}

/* -------------------------------------------------------------------------- */
/*  React                                                                     */
/* -------------------------------------------------------------------------- */

/** Subscribe a component to the client store. */
export function useAcpClient(client: AcpClient) {
  return React.useSyncExternalStore(client.subscribe, client.getState, client.getState)
}

/** The selector helpers below read the session's config options the way ACP categorises them. */
export function configByCategory(session: SessionState | undefined, category: string) {
  return session?.configOptions.find((o) => o.category === category && o.type === "select") as
    | (acp.SessionConfigOption & { type: "select"; currentValue: string; options: acp.SessionConfigSelectOptions })
    | undefined
}

/** Flatten grouped select options. */
export function flatOptions(options: acp.SessionConfigSelectOptions): (acp.SessionConfigSelectOption & { group?: string })[] {
  return options.flatMap((o) => ("options" in o ? o.options.map((x) => ({ ...x, group: o.name })) : [o]))
}

/**
 * Transports carry newline-free JSON-RPC 2.0 messages between the browser ACP
 * client and an agent. Two ship with the template:
 * - `createMockTransport()` (./mock-agent): an in-memory agent that replays a
 *   scripted coding session, so the static demo works offline;
 * - `createWebSocketTransport(url)`: a WebSocket to `server/acp-bridge.mjs`,
 *   which spawns a real ACP agent over stdio and serves fs / terminal calls.
 */

export type JsonRpcId = number | string

export type JsonRpcMessage = {
  jsonrpc: "2.0"
  id?: JsonRpcId | null
  method?: string
  params?: unknown
  result?: unknown
  error?: { code: number; message: string; data?: unknown }
}

export interface AcpTransport {
  /** Human label for the connection ("Demo agent", "ws://127.0.0.1:8787"). */
  readonly label: string
  send(message: JsonRpcMessage): void
  /** Subscribe to incoming messages; returns an unsubscribe function. */
  onMessage(listener: (message: JsonRpcMessage) => void): () => void
  /** Called once when the connection ends (agent exited, socket closed). */
  onClose(listener: (reason: string) => void): () => void
  close(): void
}

/** Small listener set shared by the transports. */
export function createEmitter<T>() {
  const listeners = new Set<(value: T) => void>()
  return {
    on(listener: (value: T) => void) {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    emit(value: T) {
      for (const l of [...listeners]) l(value)
    },
  }
}

/**
 * Open a WebSocket to the ACP bridge. Resolves once the socket is open;
 * rejects if it fails to connect (bridge not running, wrong token).
 */
export function createWebSocketTransport(url: string): Promise<AcpTransport> {
  return new Promise((resolve, reject) => {
    let ws: WebSocket
    try {
      ws = new WebSocket(url)
    } catch (err) {
      reject(err instanceof Error ? err : new Error(String(err)))
      return
    }
    const messages = createEmitter<JsonRpcMessage>()
    const closed = createEmitter<string>()
    let open = false
    ws.addEventListener("open", () => {
      open = true
      resolve({
        label: url.replace(/([?&])token=[^&]*/, "$1token=…"),
        send: (message) => {
          if (ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify(message))
        },
        onMessage: messages.on,
        onClose: closed.on,
        close: () => ws.close(),
      })
    })
    ws.addEventListener("message", (event) => {
      const text = typeof event.data === "string" ? event.data : ""
      for (const line of text.split("\n")) {
        if (!line.trim()) continue
        try {
          messages.emit(JSON.parse(line) as JsonRpcMessage)
        } catch {
          /* ignore malformed frames */
        }
      }
    })
    ws.addEventListener("close", (event) => {
      if (!open) reject(new Error(event.reason || `Could not connect to ${url}`))
      else closed.emit(event.reason || "Connection closed")
    })
    ws.addEventListener("error", () => {
      if (!open) reject(new Error(`Could not connect to ${url}. Is the bridge running?`))
    })
  })
}

import type * as acp from "@agentclientprotocol/sdk"

import {
  DEMO_CWD,
  DEMO_EDITS,
  DEMO_FILES,
  DEMO_THREADS,
  demoShell,
  fixDragReplay,
  genericReplay,
} from "./demo-data"
import { createEmitter, type AcpTransport, type JsonRpcId, type JsonRpcMessage } from "./transport"

/**
 * An in-memory ACP agent. It answers the same JSON-RPC methods a real agent
 * does (initialize, session/new, session/load, session/list, session/prompt,
 * session/cancel, session/set_mode, session/set_config_option) and plays a
 * scripted turn for every prompt: thoughts, a plan, tool calls, a permission
 * request in "Ask" mode, a diff, terminal output and a streamed answer. It
 * also fakes the bridge's `_bridge/*` methods so the explorer and terminal
 * work offline.
 */

const MODES: acp.SessionMode[] = [
  { id: "ask", name: "Ask first", description: "Ask before editing files or running commands" },
  { id: "auto", name: "Auto-edit", description: "Edit files freely, ask before commands" },
  { id: "full", name: "Full access", description: "Edit files and run commands without asking" },
]

function configOptions(model = "gpt-6.1-sol", effort = "high"): acp.SessionConfigOption[] {
  return [
    {
      id: "model",
      name: "Model",
      category: "model",
      type: "select",
      currentValue: model,
      options: [
        {
          group: "codex",
          name: "Codex",
          options: [
            { value: "gpt-6.1-sol", name: "GPT-6.1 Sol", description: "Most capable for long coding tasks" },
            { value: "gpt-6.1", name: "GPT-6.1", description: "Fast and capable" },
            { value: "gpt-6.1-mini", name: "GPT-6.1 Mini", description: "Quick edits and questions" },
          ],
        },
        {
          group: "claude",
          name: "Claude",
          options: [
            { value: "sonnet-5.5", name: "Sonnet 5.5", description: "Balanced speed and depth" },
            { value: "opus-5", name: "Opus 5", description: "Deepest reasoning" },
          ],
        },
      ],
    },
    {
      id: "effort",
      name: "Reasoning effort",
      category: "thought_level",
      type: "select",
      currentValue: effort,
      options: [
        { value: "low", name: "Low", description: "Fastest, for small edits" },
        { value: "medium", name: "Medium", description: "Balanced" },
        { value: "high", name: "High", description: "Thinks longer on hard problems" },
        { value: "xhigh", name: "Extra high", description: "Slowest, most thorough" },
      ],
    },
  ]
}

const COMMANDS: acp.AvailableCommand[] = [
  { name: "review", description: "Review the current diff before you push" },
  { name: "plan", description: "Outline the steps before editing", input: { hint: "what to plan" } },
  { name: "test", description: "Run the relevant tests and fix failures" },
  { name: "compact", description: "Summarise the conversation to free context" },
  { name: "init", description: "Write an AGENTS.md for this repository" },
  { name: "status", description: "Show model, branch and context usage" },
]

type MockSession = { mode: string; model: string; effort: string; timers: number[]; promptId: JsonRpcId | null; turn: number }

export type MockTransportOptions = {
  /** Speed multiplier for the scripted turn (2 = twice as fast). */
  speed?: number
}

export function createMockTransport({ speed = 1 }: MockTransportOptions = {}): AcpTransport {
  const toClient = createEmitter<JsonRpcMessage>()
  const closed = createEmitter<string>()
  const sessions = new Map<string, MockSession>()
  const permissionWaiters = new Map<JsonRpcId, (r: acp.RequestPermissionResponse) => void>()
  let rid = 1000
  let alive = true

  const emit = (m: Omit<JsonRpcMessage, "jsonrpc">) => {
    if (!alive) return
    // Deliver asynchronously, like a real transport.
    setTimeout(() => toClient.emit({ jsonrpc: "2.0", ...m }), 0)
  }
  const update = (sessionId: string, u: Record<string, unknown>) =>
    emit({ method: "session/update", params: { sessionId, update: u } })
  const respond = (id: JsonRpcId, result: unknown) => emit({ id, result })
  const fail = (id: JsonRpcId, code: number, message: string) => emit({ id, error: { code, message } })

  const ask = (sessionId: string, toolCall: acp.ToolCallUpdate) =>
    new Promise<acp.RequestPermissionResponse>((resolve) => {
      const id = rid++
      permissionWaiters.set(id, resolve)
      emit({
        id,
        method: "session/request_permission",
        params: {
          sessionId,
          toolCall,
          options: [
            { optionId: "allow_once", name: "Allow once", kind: "allow_once" },
            { optionId: "allow_always", name: "Always allow", kind: "allow_always" },
            { optionId: "reject_once", name: "Reject", kind: "reject_once" },
          ],
        } satisfies acp.RequestPermissionRequest,
      })
    })

  function newSession(id: string) {
    const s: MockSession = { mode: "full", model: "gpt-6.1-sol", effort: "high", timers: [], promptId: null, turn: 0 }
    sessions.set(id, s)
    setTimeout(() => update(id, { sessionUpdate: "available_commands_update", availableCommands: COMMANDS }), 30)
    return s
  }

  /** The scripted turn played for each prompt. */
  async function play(sessionId: string, promptId: JsonRpcId, text: string) {
    const s = sessions.get(sessionId)!
    s.promptId = promptId
    const turn = ++s.turn
    // Tool call ids must stay unique within the session, replayed history included.
    const tag = `${turn}-${Date.now().toString(36)}`
    const live = () => s.promptId === promptId && s.turn === turn && alive
    const wait = (ms: number) =>
      new Promise<void>((resolve) => {
        s.timers.push(window.setTimeout(resolve, ms / speed))
      })
    const say = async (kind: "agent_message_chunk" | "agent_thought_chunk", body: string, chunk = 6, every = 28) => {
      const words = body.split(/(?<=\s)/)
      for (let i = 0; i < words.length && live(); i += chunk) {
        update(sessionId, { sessionUpdate: kind, content: { type: "text", text: words.slice(i, i + chunk).join("") } })
        await wait(every)
      }
    }
    const stop = (reason: acp.StopReason) => {
      if (s.promptId !== promptId) return
      s.promptId = null
      respond(promptId, { stopReason: reason } satisfies acp.PromptResponse)
    }

    if (text.trim().startsWith("/")) {
      const name = text.trim().slice(1).split(/\s/)[0]
      await wait(400)
      await say("agent_message_chunk", name === "status"
        ? `**Status**\n\n- Model: \`${s.model}\` · effort \`${s.effort}\`\n- Mode: ${MODES.find((m) => m.id === s.mode)?.name}\n- Branch: \`feat/fix-chat-dragging\` · PR #1526\n- Context: 18% of 1M tokens used`
        : `Ran \`/${name}\`. In this demo commands are acknowledged only; connect a real agent through the bridge to run them.`)
      update(sessionId, { sessionUpdate: "usage_update", used: 182_000, size: 1_000_000 })
      return stop("end_turn")
    }

    await wait(350)
    await say("agent_thought_chunk", `Figure out what "${text.slice(0, 60)}" touches, change it, then run the checks.`, 4, 40)
    if (!live()) return
    const plan = (done: number): acp.PlanEntry[] =>
      ["Find the code involved", "Make the change", "Run lint and tests"].map((content, i) => ({
        content,
        priority: "medium",
        status: i < done ? "completed" : i === done ? "in_progress" : "pending",
      }))
    update(sessionId, { sessionUpdate: "plan", entries: plan(0) })
    update(sessionId, { sessionUpdate: "tool_call", toolCallId: `r-${tag}`, title: "Search the workspace", kind: "search", status: "in_progress" })
    await wait(900)
    update(sessionId, {
      sessionUpdate: "tool_call_update",
      toolCallId: `r-${tag}`,
      status: "completed",
      content: [{ type: "content", content: { type: "text", text: "3 matches in 2 files" } }],
    })
    update(sessionId, { sessionUpdate: "tool_call", toolCallId: `f-${tag}`, title: "Read SplitPaneLayout.tsx", kind: "read", status: "in_progress", locations: [{ path: `${DEMO_CWD}/${DEMO_EDITS[2].path}` }] })
    await wait(700)
    update(sessionId, { sessionUpdate: "tool_call_update", toolCallId: `f-${tag}`, status: "completed" })
    if (!live()) return
    update(sessionId, { sessionUpdate: "plan", entries: plan(1) })

    const path = "docs/core-concepts.md"
    const oldText = DEMO_EDITS[3].newText
    const newText = `${oldText}\n\n> ${text.replace(/\n/g, " ").slice(0, 120)}`
    const edit: acp.ToolCallUpdate = {
      toolCallId: `e-${tag}`,
      title: `Edit ${path}`,
      kind: "edit",
      status: "pending",
      locations: [{ path: `${DEMO_CWD}/${path}` }],
      content: [{ type: "diff", path, oldText, newText }],
    }
    update(sessionId, { sessionUpdate: "tool_call", ...edit, title: edit.title! })
    if (s.mode === "ask") {
      const res = await ask(sessionId, edit)
      if (!live()) return
      if (res.outcome.outcome === "cancelled") return stop("cancelled")
      if (res.outcome.optionId === "reject_once") {
        update(sessionId, { sessionUpdate: "tool_call_update", toolCallId: edit.toolCallId, status: "failed" })
        await say("agent_message_chunk", "Understood, I left the file untouched. Tell me what you would like instead.")
        return stop("end_turn")
      }
      if (res.outcome.optionId === "allow_always") {
        s.mode = "auto"
        update(sessionId, { sessionUpdate: "current_mode_update", currentModeId: "auto" })
      }
    }
    update(sessionId, { sessionUpdate: "tool_call_update", toolCallId: edit.toolCallId, status: "in_progress" })
    await wait(800)
    update(sessionId, { sessionUpdate: "tool_call_update", toolCallId: edit.toolCallId, status: "completed" })
    if (!live()) return
    update(sessionId, { sessionUpdate: "plan", entries: plan(2) })

    // A command whose output streams into an embedded terminal.
    const terminalId = `term-${sessionId}-${turn}`
    update(sessionId, {
      sessionUpdate: "tool_call",
      toolCallId: `x-${tag}`,
      title: "Run bun run test src/components/chat",
      kind: "execute",
      status: "in_progress",
      rawInput: { command: "bun run test src/components/chat" },
      content: [{ type: "terminal", terminalId }],
    })
    const lines = demoShell("bun run test").split("\n")
    for (const line of lines) {
      if (!live()) return
      emit({ method: "_bridge/terminal_output", params: { terminalId, data: `${line}\n`, title: "bun test", sessionId } })
      await wait(160)
    }
    emit({ method: "_bridge/terminal_exit", params: { terminalId, exitStatus: { exitCode: 0, signal: null } } })
    update(sessionId, { sessionUpdate: "tool_call_update", toolCallId: `x-${tag}`, status: "completed" })
    update(sessionId, { sessionUpdate: "plan", entries: plan(3) })
    if (!live()) return
    await wait(300)
    await say(
      "agent_message_chunk",
      `Done. I noted your request in \`${path}\` and re-ran the chat tests:\n\n- 46 tests pass across 2 files.\n- No lint or type errors.\n\nThis is the offline demo agent. Open **Settings → Agents** to connect Claude Code, Codex or Gemini through the ACP bridge.`
    )
    update(sessionId, { sessionUpdate: "usage_update", used: 182_000 + turn * 9_000, size: 1_000_000 })
    stop("end_turn")
  }

  function replay(sessionId: string, id: JsonRpcId) {
    const thread = DEMO_THREADS.find((t) => t.sessionId === sessionId)
    if (!thread) return fail(id, -32002, `Session ${sessionId} not found`)
    const s = sessions.get(sessionId) ?? newSession(sessionId)
    const steps = sessionId === "sess_fix_drag" ? fixDragReplay() : genericReplay(thread)
    for (const step of steps) update(sessionId, { ...step.update, _meta: { ...(step.update._meta as object), timestamp: step.at } })
    if (thread.provider === "claude") s.model = "sonnet-5.5"
    respond(id, { modes: { currentModeId: s.mode, availableModes: MODES }, configOptions: configOptions(s.model, s.effort) } satisfies acp.LoadSessionResponse)
  }

  function handle(msg: JsonRpcMessage) {
    // Responses to our requests (permission answers).
    if (!msg.method && msg.id != null) {
      const resolve = permissionWaiters.get(msg.id)
      permissionWaiters.delete(msg.id)
      resolve?.((msg.result as acp.RequestPermissionResponse) ?? { outcome: { outcome: "cancelled" } })
      return
    }
    const { id, method } = msg
    const params = (msg.params ?? {}) as Record<string, unknown>
    switch (method) {
      case "initialize":
        return respond(id!, {
          protocolVersion: 1,
          agentInfo: { name: "demo-agent", title: "Demo agent", version: "1.0.0" },
          agentCapabilities: {
            loadSession: true,
            promptCapabilities: { image: false, audio: false, embeddedContext: true },
            sessionCapabilities: { list: {} },
          },
          authMethods: [],
        } satisfies acp.InitializeResponse)
      case "session/new": {
        const sessionId = `sess_${Math.random().toString(36).slice(2, 10)}`
        const s = newSession(sessionId)
        return respond(id!, { sessionId, modes: { currentModeId: s.mode, availableModes: MODES }, configOptions: configOptions() } satisfies acp.NewSessionResponse)
      }
      case "session/list":
        return respond(id!, {
          sessions: DEMO_THREADS.map((t) => ({
            sessionId: t.sessionId,
            cwd: DEMO_CWD,
            title: t.title,
            _meta: { provider: t.provider, repo: t.repo, pr: t.pr, branch: t.branch, group: t.group },
          })),
        } satisfies acp.ListSessionsResponse)
      case "session/load":
        return replay(String(params.sessionId), id!)
      case "session/prompt": {
        const sessionId = String(params.sessionId)
        if (!sessions.has(sessionId)) newSession(sessionId)
        const prompt = (params.prompt as acp.ContentBlock[]) ?? []
        const text = prompt.map((b) => (b.type === "text" ? b.text : "")).join("")
        void play(sessionId, id!, text)
        return
      }
      case "session/cancel": {
        const s = sessions.get(String(params.sessionId))
        if (!s) return
        for (const t of s.timers) window.clearTimeout(t)
        s.timers = []
        for (const [rid, resolve] of permissionWaiters) {
          resolve({ outcome: { outcome: "cancelled" } })
          permissionWaiters.delete(rid)
        }
        if (s.promptId != null) {
          const pid = s.promptId
          s.promptId = null
          respond(pid, { stopReason: "cancelled" } satisfies acp.PromptResponse)
        }
        return
      }
      case "session/set_mode": {
        const s = sessions.get(String(params.sessionId))
        if (s) s.mode = String(params.modeId)
        respond(id!, {})
        return update(String(params.sessionId), { sessionUpdate: "current_mode_update", currentModeId: String(params.modeId) })
      }
      case "session/set_config_option": {
        const s = sessions.get(String(params.sessionId))
        if (s && params.configId === "model") s.model = String(params.value)
        if (s && params.configId === "effort") s.effort = String(params.value)
        return respond(id!, { configOptions: configOptions(s?.model, s?.effort) } satisfies acp.SetSessionConfigOptionResponse)
      }
      /* Bridge extension methods, faked for the offline demo. */
      case "_bridge/list_files":
        return respond(id!, { files: DEMO_FILES, root: DEMO_CWD })
      case "_bridge/read_file": {
        const path = String(params.path)
        const edit = DEMO_EDITS.find((e) => e.path === path)
        return respond(id!, { content: edit?.newText ?? `// ${path}\n// (demo workspace: connect the bridge to browse real files)\n` })
      }
      case "_bridge/write_file":
        return respond(id!, {})
      case "_bridge/exec": {
        const terminalId = String(params.terminalId)
        const out = demoShell(String(params.command))
        setTimeout(() => {
          emit({ method: "_bridge/terminal_output", params: { terminalId, data: out } })
          respond(id!, { exitCode: 0 })
        }, 180 / speed)
        return
      }
      default:
        if (id != null) fail(id, -32601, `Method not found: ${method}`)
    }
  }

  return {
    label: "Demo agent (offline)",
    send: (m) => {
      if (alive) setTimeout(() => handle(m), 0)
    },
    onMessage: toClient.on,
    onClose: closed.on,
    close: () => {
      alive = false
      for (const s of sessions.values()) for (const t of s.timers) window.clearTimeout(t)
      closed.emit("Closed")
    },
  }
}

